            "riskMark": "!"
          }
        }
      },
      "calendar": {
        "todayLabel": "日程",
        "event": {
          "entityName": "calendar_event",
          "entityId": "calendar-clean-116",
          "title": "18:30 视频",
          "timeRange": "18:30-19:00"
        }
      },
      "assets": {
        "scenery": "assets/memory-clean-scenery.png",
        "clockIcon": "assets/clock-alert.png"
      },
      "state": {
        "storageNearlyFull": true,
        "warningLevel": "alert"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "scenery",
      "src": "assets/memory-clean-scenery.png",
      "use": "left scenic background",
      "description": "左侧风景主视觉素材，可作为清理卡片的延伸背景，与右侧红色告警区域形成对比。",
      "bindTo": "/assets/scenery"
    },
    {
      "assetRef": "clockIcon",
      "src": "assets/clock-alert.png",
      "use": "alarm reminder icon",
      "description": "时钟图标素材，用于清理任务旁的定时提醒入口。",
      "bindTo": "/assets/clockIcon"
    }
  ]
}

